import { useState } from 'react'
import type { FormEvent } from 'react'
import { Screen, Card, Stack, TextField, Button, Alert } from '@nexti/ds'
import type { ScreenProps } from './types'

// Assumptions carried over from the approved prototype (to confirm at gate C2):
// - Option 1 (Pagar una orden) opens SCR-PAGOORD.
// - Option 2 (Consultar una orden) opens SCR-PAGORES.
// - PF3 (Salir) has no target in the contract, so it only shows a message.
const TARGETS: Record<string, string> = {
  '1': 'SCR-PAGOORD',
  '2': 'SCR-PAGORES',
}

type Tone = 'info' | 'success' | 'warning' | 'error'

function today(): string {
  const d = new Date()
  const dd = String(d.getDate()).padStart(2, '0')
  const mm = String(d.getMonth() + 1).padStart(2, '0')
  const yy = String(d.getFullYear() % 100).padStart(2, '0')
  return `${dd}/${mm}/${yy}` // 8 characters
}

function readValue(v: unknown): string {
  if (typeof v === 'string') return v
  const target = (v as { target?: { value?: unknown } } | null)?.target
  return typeof target?.value === 'string' ? target.value : ''
}

export default function PagomenScreen({ navigate }: ScreenProps) {
  const [opcion, setOpcion] = useState('')
  const [fieldError, setFieldError] = useState<string | undefined>(undefined)
  const [message, setMessage] = useState('')
  const [tone, setTone] = useState<Tone>('info')
  const fecha = today()

  const show = (text: string, t: Tone) => {
    setMessage(text)
    setTone(t)
  }

  const handleChange = (v: unknown) => {
    setOpcion(readValue(v).replace(/\D/g, '').slice(0, 1))
    setFieldError(undefined)
    if (message) show('', 'info')
  }

  const submit = (e: FormEvent) => {
    e.preventDefault()
    if (opcion.trim() === '') {
      const text = 'Ingrese una opción para continuar.'
      setFieldError(text)
      show(text, 'error')
      return
    }
    const target = TARGETS[opcion]
    if (!target) {
      const text = 'Opción inválida. Ingrese 1 o 2.'
      setFieldError(text)
      show(text, 'error')
      return
    }
    setFieldError(undefined)
    show('', 'info')
    navigate(target)
  }

  const exit = () => {
    setFieldError(undefined)
    show('Sesión finalizada. Ha salido del menú de pagos.', 'info')
  }

  const messageText = <p data-field="MENSAJE">{message}</p>

  return (
    <Screen title="BANCO FICTICIO - PAGOS">
      <form onSubmit={submit} noValidate>
        <Stack>
          <div>
            <span>FECHA: </span>
            <span data-field="FECHA">{fecha}</span>
          </div>

          <Card title="Menú de pagos">
            <Stack>
              <p>1. Pagar una orden</p>
              <p>2. Consultar una orden</p>
              <div data-field="OPCION">
                <TextField
                  label="OPCION"
                  required
                  numeric
                  maxLength={1}
                  value={opcion}
                  error={fieldError}
                  onChange={handleChange}
                />
              </div>
            </Stack>
          </Card>

          {message ? <Alert tone={tone}>{messageText}</Alert> : messageText}

          <Stack>
            <Button type="submit" variant="primary" data-action="ENTER">
              CONTINUAR
            </Button>
            <Button type="button" variant="secondary" data-action="PF3" onClick={exit}>
              SALIR
            </Button>
          </Stack>
        </Stack>
      </form>
    </Screen>
  )
}
